import { CaptionsLogger } from './CaptionsLogger.js';
import { PenState } from './PenState.js';
import type { PenStyles } from './PenStyles.js';
import { StyledUnicodeChar } from './StyledUnicodeChar.js';
import { VerboseLevel } from './VerboseLevel.js';
import { NR_COLS } from './utils/NR_COLS.js';
import { getCharForByte } from './utils/getCharForByte.js';

/**
 * CTA-608 row consisting of NR_COLS instances of StyledUnicodeChar.
 *
 * @group CTA-608
 * @beta
 */
export class Row {
	public chars: StyledUnicodeChar[] = [];
	public cueStartTime: number | null = null;

	private pos: number = 0;
	private currPenState: PenState = new PenState();
	private logger: CaptionsLogger;

	constructor(logger: CaptionsLogger = new CaptionsLogger()) {
		for (let i = 0; i < NR_COLS; i++) {
			this.chars.push(new StyledUnicodeChar());
		}
		this.logger = logger;
	}

	equals(other: Row): boolean {
		for (let i = 0; i < NR_COLS; i++) {
			if (!this.chars[i].equals(other.chars[i])) {
				return false;
			}
		}
		return true;
	}

	copy(other: Row): void {
		for (let i = 0; i < NR_COLS; i++) {
			this.chars[i].copy(other.chars[i]);
		}
	}

	isEmpty(): boolean {
		let empty = true;
		for (let i = 0; i < NR_COLS; i++) {
			if (!this.chars[i].isEmpty()) {
				empty = false;
				break;
			}
		}
		return empty;
	}

	/**
	 *  Set the cursor to a valid column.
	 */
	setCursor(absPos: number): void {
		if (this.pos !== absPos) {
			this.pos = absPos;
		}

		if (this.pos < 0) {
			this.logger.log(
				VerboseLevel.DEBUG,
				'Negative cursor position ' + this.pos,
			);
			this.pos = 0;
		}
		else if (this.pos > NR_COLS) {
			this.logger.log(
				VerboseLevel.DEBUG,
				'Too large cursor position ' + this.pos,
			);
			this.pos = NR_COLS;
		}
	}

	/**
	 * Move the cursor relative to current position.
	 */
	moveCursor(relPos: number): void {
		const newPos = this.pos + relPos;
		if (relPos > 1) {
			for (let i = this.pos + 1; i < newPos + 1; i++) {
				this.chars[i].setPenState(this.currPenState);
			}
		}
		this.setCursor(newPos);
	}

	/**
	 * Backspace, move one step back and clear character.
	 */
	backSpace(): void {
		this.moveCursor(-1);
		this.chars[this.pos].setChar(' ', this.currPenState);
	}

	insertChar(byte: number): void {
		if (byte >= 0x90) {
			// Extended char
			this.backSpace();
		}
		const char = getCharForByte(byte);
		if (this.pos >= NR_COLS) {
			this.logger.log(
				VerboseLevel.ERROR,
				() =>
					'Cannot insert ' +
					byte.toString(16) +
					' (' +
					char +
					') at position ' +
					this.pos +
					'. Skipping it!',
			);
			return;
		}
		this.chars[this.pos].setChar(char, this.currPenState);
		this.moveCursor(1);
	}

	clearFromPos(startPos: number): void {
		let i: number;
		for (i = startPos; i < NR_COLS; i++) {
			this.chars[i].reset();
		}
	}

	clear(): void {
		this.clearFromPos(0);
		this.pos = 0;
		this.currPenState.reset();
	}

	clearToEndOfRow(): void {
		this.clearFromPos(this.pos);
	}

	getTextString(): string {
		const chars: string[] = [];
		let empty = true;
		for (let i = 0; i < NR_COLS; i++) {
			const char = this.chars[i].uchar;
			if (char !== ' ') {
				empty = false;
			}

			chars.push(char);
		}
		if (empty) {
			return '';
		}
		else {
			return chars.join('');
		}
	}

	setPenStyles(styles: Partial<PenStyles>): void {
		this.currPenState.setStyles(styles);
		const currChar = this.chars[this.pos];
		currChar.setPenState(this.currPenState);
	}
}
