            return switchRequest;
        } catch (e) {
            logger.error(e);
            return SwitchRequest(context).create();
        }
    }

    function reset() {
        // no persistent information to reset
    }

    instance = {
        getSwitchRequest,
        reset
    };

    setup();

    return instance;
