function VttCustomRenderingParser() {

    let instance,
        vttjs;

    function setup() {
        try {
            if (window && window.WebVTT && window.WebVTT.Parser) {
                vttjs = new window.WebVTT.Parser(
                    window,
                    window.vttjs,
                    window.WebVTT.StringDecoder()
                );
            }
        } catch (e) {

        }
    }

    function parse(data) {
        let cues = [];
        vttjs.oncue = function (cue) {
            cue.start = cue.startTime;
            cue.end = cue.endTime;
            cue.data = cue.text;
            cue.styles = {
                align: cue.align,
                line: cue.line,
                position: cue.position,
                size: cue.size
            }
            cues.push(cue);
        };
        vttjs.parse(data);

        return cues;
    }

    instance = {
        parse
    };

    setup();
    return instance;
